import json, urllib.request, urllib.error
tok = open('/tmp/owner_tok').read().strip()
req = urllib.request.Request('https://ivx-holdings-platform.onrender.com/api/ivx/owner-variables/status', headers={'Authorization': f'Bearer {tok}'})
try:
    with urllib.request.urlopen(req, timeout=40) as r:
        d = json.loads(r.read())
    out = json.dumps(d)
    print('bytes:', len(out))
    # print variable names/keys only
    def walk(o, depth=0):
        if isinstance(o, dict):
            for k, v in o.items():
                if k in ('variables','vars','items','names','configured','missing','entries') or depth == 0:
                    print(' '*depth, k, ':', (v if isinstance(v,(int,str,bool)) else type(v).__name__))
                    walk(v, depth+1)
        elif isinstance(o, list):
            for it in o[:40]:
                if isinstance(it, dict):
                    print(' '*depth, '-', it.get('name') or it.get('key') or list(it.keys())[:3], '| set:', it.get('isSet', it.get('configured', it.get('hasValue'))))
                else:
                    print(' '*depth, '-', it)
    walk(d)
except urllib.error.HTTPError as e:
    print('HTTP', e.code, e.read().decode()[:300])
"

